// ============================================================================
// Equivalence miters: RTL generated by Chisel/firtool  vs  hand-written models (model/cr_ctl_models.sv).
// Tops: eq_ctrl #(KEEP), eq_gate_c, eq_gate_ul, eq_iso. All inputs are free; every output is compared in
// every cycle except the very first one (reset is high only there: the async-reset RTL shows its reset value
// at once, the model one edge later).
// Read with -DSYNTHESIS (drops the RTL assertions / initial blocks) and -DFORMAL (drops the models' $error).
//
// Message encoding shared by both sides (see run_equiv.sh):
//   - opcodes are built from a small free selector, so only the allowed opcodes occur (RTL: 4-bit opcode with MSB 0)
//       A: {0 PutFull, 4 Get, 6 AcquireBlock, 7 AcquirePerm}   C: {4 ProbeAck, 5 ProbeAckData, 6 Release, 7 ReleaseData}
//       D: {0 AccessAck, 1 AccessAckData, 4 Grant, 5 GrantData, 6 ReleaseAck}   B: Probe (6) always
//   - size = 4 (16 bytes = 2 beats of the 8-byte RTL beat) on every channel, address bits above 3 are zero
//   - mask all ones, corrupt/denied 0, data 0 (data is not compared, the models carry 32 bits per beat)
// ============================================================================

// ---------------------------------------------------------------------------
// reset: high in the first cycle only; first = 1 marks that cycle
module eq_rst (input logic clk, output logic rst);
  logic first = 1'b1;
  always_ff @(posedge clk) first <= 1'b0;
  assign rst = first;
endmodule

// opcode selectors: free selector -> allowed opcode (3 low bits)
function automatic logic [2:0] f_op_a(input logic [1:0] s);   // 0, 4, 6, 7
  case (s) 2'd0: f_op_a = 3'd0; 2'd1: f_op_a = 3'd4; 2'd2: f_op_a = 3'd6; default: f_op_a = 3'd7; endcase
endfunction
function automatic logic [2:0] f_op_a_ul(input logic s);       // 0, 4 (TL-UL only)
  f_op_a_ul = s ? 3'd4 : 3'd0;
endfunction
function automatic logic [2:0] f_op_c(input logic [1:0] s);   // 4..7
  f_op_c = {1'b1, s};
endfunction
function automatic logic [2:0] f_op_d(input logic [2:0] s);   // 0, 1, 4, 5, 6 (5..7 fold onto 6, 0, 1)
  case (s) 3'd0: f_op_d = 3'd0; 3'd1: f_op_d = 3'd1; 3'd2: f_op_d = 3'd4; 3'd3: f_op_d = 3'd5;
           3'd4: f_op_d = 3'd6; 3'd5: f_op_d = 3'd6; 3'd6: f_op_d = 3'd0; default: f_op_d = 3'd1; endcase
endfunction
function automatic logic [2:0] f_op_d_ul(input logic s);       // 0, 1 (TL-UL only)
  f_op_d_ul = {2'b00, s};
endfunction

// ---------------------------------------------------------------------------
// CoreResetCtrl: KEEP=1 -> CoreResetCtrl_keep, KEEP=0 -> CoreResetCtrl_sweep
module eq_ctrl #(parameter bit KEEP = 1) (
  input logic clk,
  input logic req, l1_done, l1_idle, l1_alive, core_in_reset, early_quiet, gates_quiet
);
  logic rst; eq_rst u_rst (.clk(clk), .rst(rst));
  logic first; assign first = rst;

  logic m_busy, m_in_reset, m_hart_in_reset, m_l1_req, m_l1_freeze, m_early_block, m_gate_block,
        m_hold_probe, m_ack_probe, m_isolate, m_core_reset;
  logic [2:0] m_st;
  cr_ctrl #(.KEEP(KEEP), .RST_CYCLES(100)) u_model (
    .clk(clk), .rst(rst), .req(req),
    .busy(m_busy), .in_reset(m_in_reset), .hart_in_reset(m_hart_in_reset),
    .l1_flush_req(m_l1_req), .l1_freeze(m_l1_freeze), .l1_flush_done(l1_done), .l1_idle(l1_idle),
    .l1_alive(l1_alive), .core_in_reset(core_in_reset),
    .early_block(m_early_block), .gate_block(m_gate_block), .hold_probe(m_hold_probe), .ack_probe(m_ack_probe),
    .early_quiet(early_quiet), .gates_quiet(gates_quiet),
    .isolate(m_isolate), .core_reset(m_core_reset), .st(m_st));

  logic r_busy, r_in_reset, r_hart_in_reset, r_l1_req, r_l1_freeze, r_early_block, r_gate_block,
        r_hold_probe, r_ack_probe, r_isolate, r_core_reset;
  if (KEEP) begin : g_rtl
    CoreResetCtrl_keep u_rtl (
      .clock(clk), .reset(rst), .io_req(req),
      .io_busy(r_busy), .io_inReset(r_in_reset), .io_hartInReset(r_hart_in_reset),
      .io_l1_req(r_l1_req), .io_l1_freeze(r_l1_freeze), .io_l1_done(l1_done), .io_l1_idle(l1_idle),
      .io_l1_alive(l1_alive), .io_coreInReset(core_in_reset),
      .io_earlyBlock(r_early_block), .io_gateBlock(r_gate_block), .io_holdProbe(r_hold_probe),
      .io_ackProbe(r_ack_probe), .io_isolate(r_isolate),
      .io_earlyQuiet(early_quiet), .io_gatesQuiet(gates_quiet), .io_coreReset(r_core_reset));
  end else begin : g_rtl
    CoreResetCtrl_sweep u_rtl (
      .clock(clk), .reset(rst), .io_req(req),
      .io_busy(r_busy), .io_inReset(r_in_reset), .io_hartInReset(r_hart_in_reset),
      .io_l1_req(r_l1_req), .io_l1_freeze(r_l1_freeze), .io_l1_done(l1_done), .io_l1_idle(l1_idle),
      .io_l1_alive(l1_alive), .io_coreInReset(core_in_reset),
      .io_earlyBlock(r_early_block), .io_gateBlock(r_gate_block), .io_holdProbe(r_hold_probe),
      .io_ackProbe(r_ack_probe), .io_isolate(r_isolate),
      .io_earlyQuiet(early_quiet), .io_gatesQuiet(gates_quiet), .io_coreReset(r_core_reset));
  end

  always_comb if (!first) begin
    assert (r_busy          == m_busy);
    assert (r_in_reset      == m_in_reset);
    assert (r_hart_in_reset == m_hart_in_reset);
    assert (r_l1_req        == m_l1_req);
    assert (r_l1_freeze     == m_l1_freeze);
    assert (r_early_block   == m_early_block);
    assert (r_gate_block    == m_gate_block);
    assert (r_hold_probe    == m_hold_probe);
    assert (r_ack_probe     == m_ack_probe);
    assert (r_isolate       == m_isolate);
    assert (r_core_reset    == m_core_reset);
  end
endmodule

// ---------------------------------------------------------------------------
// TLQuiesceGate (TL-C, the gate of the DCache) against cr_gate #(BCE=1).
// core side (in) = RTL auto_in_*, model i*;  L2 side (out) = RTL auto_out_*, model o*.
module eq_gate_c (
  input logic clk,
  input logic block, hold_b, ack_b, isolate,
  // A in (core)
  input logic ia_valid, input logic [1:0] ia_opsel, input logic [1:0] ia_param, input logic [3:0] ia_src, input logic [3:0] ia_addr,
  // C in (core)
  input logic ic_valid, input logic [1:0] ic_opsel, input logic [2:0] ic_param, input logic [3:0] ic_src, input logic [3:0] ic_addr,
  // E in (core)
  input logic ie_valid, input logic [3:0] ie_sink,
  // ready of the core side (B, D)
  input logic ib_ready, id_ready,
  // A, C, E ready of L2
  input logic oa_ready, oc_ready, oe_ready,
  // B out (L2)
  input logic ob_valid, input logic [1:0] ob_param, input logic [3:0] ob_addr,
  // D out (L2)
  input logic od_valid, input logic [2:0] od_opsel, input logic [1:0] od_param, input logic [3:0] od_src, input logic [3:0] od_sink
);
  logic rst; eq_rst u_rst (.clk(clk), .rst(rst));
  wire first = rst;

  wire [2:0] ia_op = f_op_a(ia_opsel), ic_op = f_op_c(ic_opsel), od_op = f_op_d(od_opsel);

  // model outputs
  logic m_quiet, m_ack_pend;
  logic m_ia_ready, m_ib_valid, m_ic_ready, m_id_valid, m_ie_ready;
  logic [1:0] m_ib_param; logic [3:0] m_ib_addr;
  logic [2:0] m_id_op; logic [1:0] m_id_param; logic [3:0] m_id_src, m_id_sink; logic [31:0] m_id_data;
  logic m_oa_valid, m_ob_ready, m_oc_valid, m_od_ready, m_oe_valid;
  logic [2:0] m_oa_op; logic [1:0] m_oa_param; logic [3:0] m_oa_src, m_oa_addr; logic [31:0] m_oa_data;
  logic [2:0] m_oc_op, m_oc_param; logic [3:0] m_oc_src, m_oc_addr; logic [31:0] m_oc_data;
  logic [3:0] m_oe_sink;
  cr_gate #(.BCE(1), .NAME("eq_c")) u_model (
    .clk(clk), .rst(rst), .block(block), .hold_b(hold_b), .ack_b(ack_b), .quiet(m_quiet),
    .isolate(isolate), .ack_pend(m_ack_pend),
    .ia_valid(ia_valid), .ia_ready(m_ia_ready), .ia_op(ia_op), .ia_param(ia_param), .ia_src(ia_src),
    .ia_addr(ia_addr), .ia_data(32'd0),
    .ib_valid(m_ib_valid), .ib_ready(ib_ready), .ib_param(m_ib_param), .ib_addr(m_ib_addr),
    .ic_valid(ic_valid), .ic_ready(m_ic_ready), .ic_op(ic_op), .ic_param(ic_param), .ic_src(ic_src),
    .ic_addr(ic_addr), .ic_data(32'd0),
    .id_valid(m_id_valid), .id_ready(id_ready), .id_op(m_id_op), .id_param(m_id_param), .id_src(m_id_src),
    .id_sink(m_id_sink), .id_data(m_id_data),
    .ie_valid(ie_valid), .ie_ready(m_ie_ready), .ie_sink(ie_sink),
    .oa_valid(m_oa_valid), .oa_ready(oa_ready), .oa_op(m_oa_op), .oa_param(m_oa_param), .oa_src(m_oa_src),
    .oa_addr(m_oa_addr), .oa_data(m_oa_data),
    .ob_valid(ob_valid), .ob_ready(m_ob_ready), .ob_param(ob_param), .ob_addr(ob_addr),
    .oc_valid(m_oc_valid), .oc_ready(oc_ready), .oc_op(m_oc_op), .oc_param(m_oc_param), .oc_src(m_oc_src),
    .oc_addr(m_oc_addr), .oc_data(m_oc_data),
    .od_valid(od_valid), .od_ready(m_od_ready), .od_op(od_op), .od_param(od_param), .od_src(od_src),
    .od_sink(od_sink), .od_data(32'd0),
    .oe_valid(m_oe_valid), .oe_ready(oe_ready), .oe_sink(m_oe_sink));

  // RTL outputs
  logic r_quiet;
  logic r_ia_ready, r_ib_valid, r_ic_ready, r_id_valid, r_ie_ready;
  logic [2:0] r_ib_opcode, r_ib_size; logic [1:0] r_ib_param; logic [3:0] r_ib_source; logic [15:0] r_ib_address;
  logic [7:0] r_ib_mask; logic [63:0] r_ib_data; logic r_ib_corrupt;
  logic [3:0] r_id_opcode, r_id_source, r_id_sink; logic [1:0] r_id_param; logic [2:0] r_id_size;
  logic r_id_denied, r_id_corrupt; logic [63:0] r_id_data;
  logic r_oa_valid, r_ob_ready, r_oc_valid, r_od_ready, r_oe_valid;
  logic [3:0] r_oa_opcode, r_oa_source; logic [2:0] r_oa_param, r_oa_size; logic [15:0] r_oa_address;
  logic [7:0] r_oa_mask; logic [63:0] r_oa_data; logic r_oa_corrupt;
  logic [2:0] r_oc_opcode, r_oc_param, r_oc_size; logic [3:0] r_oc_source; logic [15:0] r_oc_address;
  logic [63:0] r_oc_data; logic r_oc_corrupt;
  logic [3:0] r_oe_sink;
  TLQuiesceGate u_rtl (
    .clock(clk), .reset(rst),
    .auto_in_a_ready(r_ia_ready), .auto_in_a_valid(ia_valid), .auto_in_a_bits_opcode({1'b0, ia_op}),
    .auto_in_a_bits_param({1'b0, ia_param}), .auto_in_a_bits_size(3'd4), .auto_in_a_bits_source(ia_src),
    .auto_in_a_bits_address({12'd0, ia_addr}), .auto_in_a_bits_mask(8'hff), .auto_in_a_bits_data(64'd0),
    .auto_in_a_bits_corrupt(1'b0),
    .auto_in_b_ready(ib_ready), .auto_in_b_valid(r_ib_valid), .auto_in_b_bits_opcode(r_ib_opcode),
    .auto_in_b_bits_param(r_ib_param), .auto_in_b_bits_size(r_ib_size), .auto_in_b_bits_source(r_ib_source),
    .auto_in_b_bits_address(r_ib_address), .auto_in_b_bits_mask(r_ib_mask), .auto_in_b_bits_data(r_ib_data),
    .auto_in_b_bits_corrupt(r_ib_corrupt),
    .auto_in_c_ready(r_ic_ready), .auto_in_c_valid(ic_valid), .auto_in_c_bits_opcode(ic_op),
    .auto_in_c_bits_param(ic_param), .auto_in_c_bits_size(3'd4), .auto_in_c_bits_source(ic_src),
    .auto_in_c_bits_address({12'd0, ic_addr}), .auto_in_c_bits_data(64'd0), .auto_in_c_bits_corrupt(1'b0),
    .auto_in_d_ready(id_ready), .auto_in_d_valid(r_id_valid), .auto_in_d_bits_opcode(r_id_opcode),
    .auto_in_d_bits_param(r_id_param), .auto_in_d_bits_size(r_id_size), .auto_in_d_bits_source(r_id_source),
    .auto_in_d_bits_sink(r_id_sink), .auto_in_d_bits_denied(r_id_denied), .auto_in_d_bits_data(r_id_data),
    .auto_in_d_bits_corrupt(r_id_corrupt),
    .auto_in_e_ready(r_ie_ready), .auto_in_e_valid(ie_valid), .auto_in_e_bits_sink(ie_sink),
    .auto_out_a_ready(oa_ready), .auto_out_a_valid(r_oa_valid), .auto_out_a_bits_opcode(r_oa_opcode),
    .auto_out_a_bits_param(r_oa_param), .auto_out_a_bits_size(r_oa_size), .auto_out_a_bits_source(r_oa_source),
    .auto_out_a_bits_address(r_oa_address), .auto_out_a_bits_mask(r_oa_mask), .auto_out_a_bits_data(r_oa_data),
    .auto_out_a_bits_corrupt(r_oa_corrupt),
    .auto_out_b_ready(r_ob_ready), .auto_out_b_valid(ob_valid), .auto_out_b_bits_opcode(3'd6),
    .auto_out_b_bits_param(ob_param), .auto_out_b_bits_size(3'd4), .auto_out_b_bits_source(4'd0),
    .auto_out_b_bits_address({12'd0, ob_addr}), .auto_out_b_bits_mask(8'hff), .auto_out_b_bits_data(64'd0),
    .auto_out_b_bits_corrupt(1'b0),
    .auto_out_c_ready(oc_ready), .auto_out_c_valid(r_oc_valid), .auto_out_c_bits_opcode(r_oc_opcode),
    .auto_out_c_bits_param(r_oc_param), .auto_out_c_bits_size(r_oc_size), .auto_out_c_bits_source(r_oc_source),
    .auto_out_c_bits_address(r_oc_address), .auto_out_c_bits_data(r_oc_data), .auto_out_c_bits_corrupt(r_oc_corrupt),
    .auto_out_d_ready(r_od_ready), .auto_out_d_valid(od_valid), .auto_out_d_bits_opcode({1'b0, od_op}),
    .auto_out_d_bits_param(od_param), .auto_out_d_bits_size(3'd4), .auto_out_d_bits_source(od_src),
    .auto_out_d_bits_sink(od_sink), .auto_out_d_bits_denied(1'b0), .auto_out_d_bits_data(64'd0),
    .auto_out_d_bits_corrupt(1'b0),
    .auto_out_e_ready(oe_ready), .auto_out_e_valid(r_oe_valid), .auto_out_e_bits_sink(r_oe_sink),
    .io_block(block), .io_holdB(hold_b), .io_ackB(ack_b), .io_isolate(isolate), .io_quiet(r_quiet));

  always_comb if (!first) begin
    assert (r_quiet    == m_quiet);
    // valid / ready of every channel, both sides
    assert (r_ia_ready == m_ia_ready);  assert (r_oa_valid == m_oa_valid);
    assert (r_ib_valid == m_ib_valid);  assert (r_ob_ready == m_ob_ready);
    assert (r_ic_ready == m_ic_ready);  assert (r_oc_valid == m_oc_valid);
    assert (r_id_valid == m_id_valid);  assert (r_od_ready == m_od_ready);
    assert (r_ie_ready == m_ie_ready);  assert (r_oe_valid == m_oe_valid);
    // C towards L2: opcode and param (the gate sends its own ProbeAck NtoN)
    assert (r_oc_opcode == m_oc_op);
    assert (r_oc_param  == m_oc_param);
  end
endmodule

// ---------------------------------------------------------------------------
// TLQuiesceGate_1 (TL-UL, early gate) against cr_gate #(BCE=0): channels A and D only.
// The RTL has no B/C/E ports; the model's B/C/E inputs are tied off (its BCE=0 branch ignores them).
module eq_gate_ul (
  input logic clk,
  input logic block, isolate,
  input logic ia_valid, input logic [1:0] ia_opsel, input logic [1:0] ia_param, input logic [3:0] ia_src, input logic [3:0] ia_addr,
  input logic id_ready, oa_ready,
  input logic od_valid, input logic [2:0] od_opsel, input logic [1:0] od_param, input logic [3:0] od_src, input logic od_sink
);
  logic rst; eq_rst u_rst (.clk(clk), .rst(rst));
  wire first = rst;

  wire [2:0] ia_op = f_op_a(ia_opsel), od_op = f_op_d(od_opsel);

  logic m_quiet, m_ack_pend, m_ia_ready, m_ib_valid, m_ic_ready, m_id_valid, m_ie_ready;
  logic [1:0] m_ib_param; logic [3:0] m_ib_addr;
  logic [2:0] m_id_op; logic [1:0] m_id_param; logic [3:0] m_id_src, m_id_sink; logic [31:0] m_id_data;
  logic m_oa_valid, m_ob_ready, m_oc_valid, m_od_ready, m_oe_valid;
  logic [2:0] m_oa_op; logic [1:0] m_oa_param; logic [3:0] m_oa_src, m_oa_addr; logic [31:0] m_oa_data;
  logic [2:0] m_oc_op, m_oc_param; logic [3:0] m_oc_src, m_oc_addr; logic [31:0] m_oc_data;
  logic [3:0] m_oe_sink;
  cr_gate #(.BCE(0), .NAME("eq_ul")) u_model (
    .clk(clk), .rst(rst), .block(block), .hold_b(1'b0), .ack_b(1'b0), .quiet(m_quiet),
    .isolate(isolate), .ack_pend(m_ack_pend),
    .ia_valid(ia_valid), .ia_ready(m_ia_ready), .ia_op(ia_op), .ia_param(ia_param), .ia_src(ia_src),
    .ia_addr(ia_addr), .ia_data(32'd0),
    .ib_valid(m_ib_valid), .ib_ready(1'b0), .ib_param(m_ib_param), .ib_addr(m_ib_addr),
    .ic_valid(1'b0), .ic_ready(m_ic_ready), .ic_op(3'd0), .ic_param(3'd0), .ic_src(4'd0),
    .ic_addr(4'd0), .ic_data(32'd0),
    .id_valid(m_id_valid), .id_ready(id_ready), .id_op(m_id_op), .id_param(m_id_param), .id_src(m_id_src),
    .id_sink(m_id_sink), .id_data(m_id_data),
    .ie_valid(1'b0), .ie_ready(m_ie_ready), .ie_sink(4'd0),
    .oa_valid(m_oa_valid), .oa_ready(oa_ready), .oa_op(m_oa_op), .oa_param(m_oa_param), .oa_src(m_oa_src),
    .oa_addr(m_oa_addr), .oa_data(m_oa_data),
    .ob_valid(1'b0), .ob_ready(m_ob_ready), .ob_param(2'd0), .ob_addr(4'd0),
    .oc_valid(m_oc_valid), .oc_ready(1'b0), .oc_op(m_oc_op), .oc_param(m_oc_param), .oc_src(m_oc_src),
    .oc_addr(m_oc_addr), .oc_data(m_oc_data),
    .od_valid(od_valid), .od_ready(m_od_ready), .od_op(od_op), .od_param(od_param), .od_src(od_src),
    .od_sink({3'd0, od_sink}), .od_data(32'd0),
    .oe_valid(m_oe_valid), .oe_ready(1'b0), .oe_sink(m_oe_sink));

  logic r_quiet, r_ia_ready, r_id_valid, r_oa_valid, r_od_ready;
  logic [3:0] r_id_opcode, r_id_source, r_oa_opcode, r_oa_source; logic [1:0] r_id_param; logic [2:0] r_id_size;
  logic r_id_sink, r_id_denied, r_id_corrupt; logic [63:0] r_id_data;
  logic [2:0] r_oa_param, r_oa_size; logic [15:0] r_oa_address; logic [7:0] r_oa_mask; logic [63:0] r_oa_data;
  logic r_oa_corrupt;
  TLQuiesceGate_1 u_rtl (
    .clock(clk), .reset(rst),
    .auto_in_a_ready(r_ia_ready), .auto_in_a_valid(ia_valid), .auto_in_a_bits_opcode({1'b0, ia_op}),
    .auto_in_a_bits_param({1'b0, ia_param}), .auto_in_a_bits_size(3'd4), .auto_in_a_bits_source(ia_src),
    .auto_in_a_bits_address({12'd0, ia_addr}), .auto_in_a_bits_mask(8'hff), .auto_in_a_bits_data(64'd0),
    .auto_in_a_bits_corrupt(1'b0),
    .auto_in_d_ready(id_ready), .auto_in_d_valid(r_id_valid), .auto_in_d_bits_opcode(r_id_opcode),
    .auto_in_d_bits_param(r_id_param), .auto_in_d_bits_size(r_id_size), .auto_in_d_bits_source(r_id_source),
    .auto_in_d_bits_sink(r_id_sink), .auto_in_d_bits_denied(r_id_denied), .auto_in_d_bits_data(r_id_data),
    .auto_in_d_bits_corrupt(r_id_corrupt),
    .auto_out_a_ready(oa_ready), .auto_out_a_valid(r_oa_valid), .auto_out_a_bits_opcode(r_oa_opcode),
    .auto_out_a_bits_param(r_oa_param), .auto_out_a_bits_size(r_oa_size), .auto_out_a_bits_source(r_oa_source),
    .auto_out_a_bits_address(r_oa_address), .auto_out_a_bits_mask(r_oa_mask), .auto_out_a_bits_data(r_oa_data),
    .auto_out_a_bits_corrupt(r_oa_corrupt),
    .auto_out_d_ready(r_od_ready), .auto_out_d_valid(od_valid), .auto_out_d_bits_opcode({1'b0, od_op}),
    .auto_out_d_bits_param(od_param), .auto_out_d_bits_size(3'd4), .auto_out_d_bits_source(od_src),
    .auto_out_d_bits_sink(od_sink), .auto_out_d_bits_denied(1'b0), .auto_out_d_bits_data(64'd0),
    .auto_out_d_bits_corrupt(1'b0),
    .io_block(block), .io_isolate(isolate), .io_quiet(r_quiet));

  always_comb if (!first) begin
    assert (r_quiet    == m_quiet);
    assert (r_ia_ready == m_ia_ready);  assert (r_oa_valid == m_oa_valid);
    assert (r_id_valid == m_id_valid);  assert (r_od_ready == m_od_ready);
  end
endmodule

// ---------------------------------------------------------------------------
// TLResetIsolation against cr_iso (TL-UL: A opcodes {0 PutFull, 4 Get}, D opcodes {0 AccessAck, 1 AccessAckData};
// D 4/5 are excluded because the model's data flag is op==1 only while the RTL looks at opcode[0]).
module eq_iso (
  input logic clk,
  input logic isolate,
  input logic ia_valid, input logic ia_opsel, input logic [1:0] ia_param, input logic [3:0] ia_src, input logic [3:0] ia_addr,
  input logic id_ready, oa_ready,
  input logic od_valid, input logic od_opsel, input logic [1:0] od_param, input logic [3:0] od_src, input logic od_sink
);
  logic rst; eq_rst u_rst (.clk(clk), .rst(rst));
  wire first = rst;

  wire [2:0] ia_op = f_op_a_ul(ia_opsel), od_op = f_op_d_ul(od_opsel);

  logic m_quiet, m_ia_ready, m_id_valid, m_oa_valid, m_od_ready;
  logic [2:0] m_id_op, m_oa_op; logic [3:0] m_id_src, m_oa_src, m_oa_addr; logic [31:0] m_id_data, m_oa_data;
  cr_iso #(.NAME("eq_iso")) u_model (
    .clk(clk), .rst(rst), .isolate(isolate), .quiet(m_quiet),
    .ia_valid(ia_valid), .ia_ready(m_ia_ready), .ia_op(ia_op), .ia_src(ia_src), .ia_addr(ia_addr), .ia_data(32'd0),
    .id_valid(m_id_valid), .id_ready(id_ready), .id_op(m_id_op), .id_src(m_id_src), .id_data(m_id_data),
    .oa_valid(m_oa_valid), .oa_ready(oa_ready), .oa_op(m_oa_op), .oa_src(m_oa_src), .oa_addr(m_oa_addr),
    .oa_data(m_oa_data),
    .od_valid(od_valid), .od_ready(m_od_ready), .od_op(od_op), .od_src(od_src), .od_data(32'd0));

  logic r_quiet, r_ia_ready, r_id_valid, r_oa_valid, r_od_ready;
  logic [3:0] r_id_opcode, r_id_source, r_oa_opcode, r_oa_source; logic [1:0] r_id_param; logic [2:0] r_id_size;
  logic r_id_sink, r_id_denied, r_id_corrupt; logic [63:0] r_id_data;
  logic [2:0] r_oa_param, r_oa_size; logic [15:0] r_oa_address; logic [7:0] r_oa_mask; logic [63:0] r_oa_data;
  logic r_oa_corrupt;
  TLResetIsolation u_rtl (
    .clock(clk), .reset(rst),
    .auto_in_a_ready(r_ia_ready), .auto_in_a_valid(ia_valid), .auto_in_a_bits_opcode({1'b0, ia_op}),
    .auto_in_a_bits_param({1'b0, ia_param}), .auto_in_a_bits_size(3'd4), .auto_in_a_bits_source(ia_src),
    .auto_in_a_bits_address({12'd0, ia_addr}), .auto_in_a_bits_mask(8'hff), .auto_in_a_bits_data(64'd0),
    .auto_in_a_bits_corrupt(1'b0),
    .auto_in_d_ready(id_ready), .auto_in_d_valid(r_id_valid), .auto_in_d_bits_opcode(r_id_opcode),
    .auto_in_d_bits_param(r_id_param), .auto_in_d_bits_size(r_id_size), .auto_in_d_bits_source(r_id_source),
    .auto_in_d_bits_sink(r_id_sink), .auto_in_d_bits_denied(r_id_denied), .auto_in_d_bits_data(r_id_data),
    .auto_in_d_bits_corrupt(r_id_corrupt),
    .auto_out_a_ready(oa_ready), .auto_out_a_valid(r_oa_valid), .auto_out_a_bits_opcode(r_oa_opcode),
    .auto_out_a_bits_param(r_oa_param), .auto_out_a_bits_size(r_oa_size), .auto_out_a_bits_source(r_oa_source),
    .auto_out_a_bits_address(r_oa_address), .auto_out_a_bits_mask(r_oa_mask), .auto_out_a_bits_data(r_oa_data),
    .auto_out_a_bits_corrupt(r_oa_corrupt),
    .auto_out_d_ready(r_od_ready), .auto_out_d_valid(od_valid), .auto_out_d_bits_opcode({1'b0, od_op}),
    .auto_out_d_bits_param(od_param), .auto_out_d_bits_size(3'd4), .auto_out_d_bits_source(od_src),
    .auto_out_d_bits_sink(od_sink), .auto_out_d_bits_denied(1'b0), .auto_out_d_bits_data(64'd0),
    .auto_out_d_bits_corrupt(1'b0),
    .io_isolate(isolate), .io_quiet(r_quiet));

  always_comb if (!first) begin
    assert (r_quiet    == m_quiet);
    assert (r_ia_ready == m_ia_ready);  assert (r_oa_valid == m_oa_valid);
    assert (r_id_valid == m_id_valid);  assert (r_od_ready == m_od_ready);
  end
endmodule
